// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 baseReserve, uint256 quoteReserve, uint256 baseTarget, uint256 quoteTarget) public {
        // Restrict to admissible domain: avoid overflow in uint112, and satisfy BELOW_ONE condition with BASE_RESERVE_ < BASE_TARGET_.
        vm.assume(baseReserve <= type(uint112).max);
        vm.assume(quoteReserve <= type(uint112).max);
        vm.assume(baseTarget <= type(uint112).max);
        vm.assume(quoteTarget <= type(uint112).max);
        vm.assume(baseTarget > baseReserve);

        // Set internal state directly via storage slots (only way to prepare the exact state needed).
        // _RState_ is uint32 stored at a known slot; we must compute slot offsets from contract layout.
        // GSPStorage layout (in C):
        // ReentrancyGuard: _status slot 0
        // GSPStorage: _GSP_INITIALIZED_ slot 1, _IS_OPEN_TWAP_ slot 2, _MAINTAINER_ slot 3,
        // _BASE_TOKEN_ slot 4, _QUOTE_TOKEN_ slot 5, _BASE_RESERVE_ slot 6, _QUOTE_RESERVE_ slot 7,
        // _BLOCK_TIMESTAMP_LAST_ slot 8, _BASE_PRICE_CUMULATIVE_LAST_ slot 9,
        // _BASE_TARGET_ slot 10, _QUOTE_TARGET_ slot 11, _RState_ slot 12
        // But we don't need actual token contracts; we only need to set reserves and targets and RState.
        // We'll use vm.store to set them.

        // Set _RState_ to BELOW_ONE (1)
        vm.store(address(c), bytes32(uint256(12)), bytes32(uint256(1)));
        // Set _BASE_RESERVE_
        vm.store(address(c), bytes32(uint256(6)), bytes32(uint256(baseReserve)));
        // Set _QUOTE_RESERVE_
        vm.store(address(c), bytes32(uint256(7)), bytes32(uint256(quoteReserve)));
        // Set _BASE_TARGET_
        vm.store(address(c), bytes32(uint256(10)), bytes32(uint256(baseTarget)));
        // Set _QUOTE_TARGET_
        vm.store(address(c), bytes32(uint256(11)), bytes32(uint256(quoteTarget)));

        // Call correctRState
        c.correctRState();

        // After correctRState, the rule: _BASE_TARGET_ must equal _BASE_RESERVE_
        uint256 actualBaseTarget = c._BASE_TARGET_();
        uint256 actualBaseReserve = c._BASE_RESERVE_();
        assertTrue(actualBaseTarget == actualBaseReserve, "_BASE_TARGET_ not updated to _BASE_RESERVE_");
    }
}

