pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint112 baseReserve, uint112 quoteReserve, uint112 baseTarget, uint112 quoteTarget) public {
        // Admissible domain: BELOW_ONE state requires baseReserve < baseTarget
        vm.assume(baseReserve < baseTarget);
        vm.assume(baseReserve > 0);
        vm.assume(quoteReserve > 0);
        vm.assume(baseTarget > 0);
        vm.assume(quoteTarget > 0);

        // Use vm.store to set internal state for the test to simulate a BELOW_ONE condition.
        // Storage layout:
        // _BASE_RESERVE_ (slot 4), _QUOTE_RESERVE_ (slot 5)
        // _BASE_TARGET_ (slot 8), _QUOTE_TARGET_ (slot 9)
        // _RState_ (slot 10)
        // We need RState to be BELOW_ONE (which is 2 in the enum).
        vm.store(address(c), bytes32(uint256(4)), bytes32(uint256(baseReserve)));
        vm.store(address(c), bytes32(uint256(5)), bytes32(uint256(quoteReserve)));
        vm.store(address(c), bytes32(uint256(8)), bytes32(uint256(baseTarget)));
        vm.store(address(c), bytes32(uint256(9)), bytes32(uint256(quoteTarget)));
        vm.store(address(c), bytes32(uint256(10)), bytes32(uint256(2))); // BELOW_ONE

        // Record mid-price before the state transition
        uint256 midPriceBefore = c.getMidPrice();

        // Trigger correctRState
        c.correctRState();

        // Record mid-price after the transition
        uint256 midPriceAfter = c.getMidPrice();

        // After the transition, the state should be ONE (targets equal reserves).
        // In the reference contract, _BASE_TARGET_ is set to _BASE_RESERVE_, so the mid-price
        // calculation remains consistent with the actual reserves.
        // The buggy version leaves _BASE_TARGET_ unchanged, which affects the mid-price formula
        // and causes a different value from what a correct ONE-state price would be.
        // Since the correct contract sets _BASE_TARGET_ = _BASE_RESERVE_, the mid-price after
        // correction should equal the mid-price before correction, because the reserves are the same
        // and the target is updated to match.
        assertTrue(midPriceBefore == midPriceAfter);
    }
}

